   1: // ============================================================
   2: // Agent Loop — The heart of the system
   3: // ============================================================
   4: 
   5: import type {
   6:   AskUserFn,
   7:   HookRunner,
   8:   LoopEvent,
   9:   LoopOptions,
  10:   Message,
  11:   ModelCaller,
  12:   ModelConfig,
  13:   Tool,
  14:   ToolCall,
  15:   ToolContext,
  16:   ToolExecutionResult,
  17: } from "./types.js";
  18: import { checkPermission } from "./permissions.js";
  19: 
  20: // Default approver used when the caller (CLI) does not supply one — e.g.
  21: // sub-agents and tests. Preserves backward-compatible "allow" behavior;
  22: // plan-mode blocking is still enforced inside checkPermission().
  23: const defaultAskUser: AskUserFn = async () => true;
  24: 
  25: // --- Agent Loop (Async Generator) ---
  26: 
  27: export async function* agentLoop(
  28:   messages: Message[],
  29:   tools: Tool[],
  30:   callModel: ModelCaller,
  31:   modelConfig: ModelConfig,
  32:   options: LoopOptions,
  33: ): AsyncGenerator<LoopEvent> {
  34:   const {
  35:     maxTurns = 50,
  36:     autoCompactThreshold = 150_000,
  37:     systemPrompt,
  38:     abortSignal,
  39:     toolContext,
  40:     askUser = defaultAskUser,
  41:     hooks,
  42:   } = options;
  43: 
  44:   // Build the full ToolContext from caller-provided values, falling back to
  45:   // sensible defaults. This replaces the previously hardcoded context.
  46:   const baseContext: ToolContext = {
  47:     workspaceRoot: toolContext?.workspaceRoot ?? process.cwd(),
  48:     sessionId: toolContext?.sessionId ?? "default",
  49:     permissionMode: toolContext?.permissionMode ?? "default",
  50:     modelConfig: toolContext?.modelConfig ?? modelConfig,
  51:     onSubAgentProgress: toolContext?.onSubAgentProgress,
  52:   };
  53: 
  54:   let turnCount = 0;
  55:   let totalTokens = 0;
  56: 
  57:   while (turnCount < maxTurns) {
  58:     // Check for abort
  59:     if (abortSignal?.aborted) {
  60:       yield { type: "aborted", reason: abortSignal.reason };
  61:       return;
  62:     }
  63: 
  64:     // === STEP 1: Check if compaction is needed ===
  65:     if (estimateTokens(messages) > autoCompactThreshold) {
  66:       yield { type: "compacting" };
  67:       messages = await autoCompact(messages, callModel, modelConfig);
  68:       yield { type: "compacted", summary: "Context compressed" };
  69:     }
  70: 
  71:     // === STEP 2: Call the LLM ===
  72:     yield { type: "thinking" };
  73: 
  74:     let textBuffer = "";
  75:     const toolCalls: ToolCall[] = [];
  76:     let usage: { input_tokens: number; output_tokens: number } | null = null;
  77: 
  78:     try {
  79:       for await (const event of callModel(
  80:         messages,
  81:         tools,
  82:         systemPrompt,
  83:         modelConfig,
  84:       )) {
  85:         switch (event.type) {
  86:           case "text_delta":
  87:             textBuffer += event.delta;
  88:             yield { type: "text_delta", delta: event.delta };
  89:             break;
  90: 
  91:           case "tool_use":
  92:             toolCalls.push({
  93:               id: event.id,
  94:               type: "function",
  95:               function: {
  96:                 name: event.name,
  97:                 arguments: JSON.stringify(event.input),
  98:               },
  99:             });
 100:             yield {
 101:               type: "tool_use",
 102:               name: event.name,
 103:               input: event.input,
 104:             };
 105:             break;
 106: 
 107:           case "done":
 108:             usage = event.usage;
 109:             totalTokens += usage.input_tokens + usage.output_tokens;
 110:             yield { type: "usage", usage };
 111:             break;
 112: 
 113:           case "error":
 114:             // Handle recoverable errors
 115:             const recovery = await handleModelError(
 116:               event.error,
 117:               messages,
 118:               callModel,
 119:               modelConfig,
 120:             );
 121:             if (recovery === "retry") continue;
 122:             if (recovery === "abort") {
 123:               yield { type: "error", error: event.error };
 124:               return;
 125:             }
 126:             break;
 127:         }
 128:       }
 129:     } catch (error) {
 130:       yield { type: "error", error };
 131:       return;
 132:     }
 133: 
 134:     // === STEP 3: If no tool calls, we're done ===
 135:     if (toolCalls.length === 0) {
 136:       // Save the assistant's text response to message history
 137:       if (textBuffer) {
 138:         messages.push({
 139:           role: "assistant",
 140:           content: textBuffer,
 141:         });
 142:       }
 143:       yield {
 144:         type: "done",
 145:         finishReason: "end_turn",
 146:         turns: turnCount,
 147:       };
 148:       return;
 149:     }
 150: 
 151:     // === STEP 4: Add assistant message to history ===
 152:     messages.push({
 153:       role: "assistant",
 154:       content: textBuffer || null,
 155:       tool_calls: toolCalls,
 156:     });
 157: 
 158:     // === STEP 5: Execute tool calls (parallel for safe ones) ===
 159:     const toolResults = await executeToolCalls(
 160:       toolCalls,
 161:       tools,
 162:       baseContext,
 163:       askUser,
 164:       abortSignal,
 165:       hooks,
 166:     );
 167: 
 168:     // === STEP 6: Add tool results to history ===
 169:     for (let i = 0; i < toolCalls.length; i++) {
 170:       messages.push({
 171:         role: "tool",
 172:         tool_call_id: toolCalls[i].id,
 173:         name: toolCalls[i].function.name,
 174:         content: toolResults[i].formatted,
 175:       });
 176:     }
 177: 
 178:     // Tool results may carry images (e.g. Read on a PNG/PDF). Both providers
 179:     // accept images only in user content, so inject them as a follow-up user
 180:     // message right after the tool results that produced them.
 181:     const images = toolResults.flatMap((r) => r.result?.images ?? []);
 182:     if (images.length > 0) {
 183:       messages.push({
 184:         role: "user",
 185:         content: [
 186:           { type: "text", text: "Attached image(s) from the tool result above:" },
 187:           ...images,
 188:         ],
 189:       });
 190:     }
 191: 
 192:     yield { type: "tool_results", results: toolResults };
 193: 
 194:     turnCount++;
 195:   }
 196: 
 197:   // Max turns reached
 198:   yield {
 199:     type: "done",
 200:     finishReason: "max_turns",
 201:     turns: turnCount,
 202:     message: "Maximum turns reached. Continue?",
 203:   };
 204: }
 205: 
 206: // --- Tool Call Execution ---
 207: 
 208: async function executeToolCalls(
 209:   toolCalls: ToolCall[],
 210:   tools: Tool[],
 211:   context: ToolContext,
 212:   askUser: AskUserFn,
 213:   abortSignal?: AbortSignal,
 214:   hooks?: HookRunner,
 215: ): Promise<ToolExecutionResult[]> {
 216:   // Separate into parallel-safe and serial groups
 217:   const parallelCalls: ToolCall[] = [];
 218:   const serialCalls: ToolCall[] = [];
 219: 
 220:   for (const call of toolCalls) {
 221:     const tool = tools.find((t) => t.name === call.function.name);
 222:     if (!tool) {
 223:       serialCalls.push(call);
 224:       continue;
 225:     }
 226:     if (tool.isConcurrencySafe()) {
 227:       parallelCalls.push(call);
 228:     } else {
 229:       serialCalls.push(call);
 230:     }
 231:   }
 232: 
 233:   const results: ToolExecutionResult[] = [];
 234: 
 235:   // Execute parallel-safe calls simultaneously
 236:   if (parallelCalls.length > 0) {
 237:     const parallelResults = await Promise.all(
 238:       parallelCalls.map((call) =>
 239:         executeSingleTool(call, tools, context, askUser, hooks),
 240:       ),
 241:     );
 242:     results.push(...parallelResults);
 243:   }
 244: 
 245:   // Execute serial calls one at a time
 246:   for (const call of serialCalls) {
 247:     // Allow long serial sequences to stop early on abort.
 248:     if (abortSignal?.aborted) {
 249:       results.push({
 250:         toolName: call.function.name,
 251:         error: "Aborted",
 252:         formatted: `Aborted before executing ${call.function.name}.`,
 253:       });
 254:       continue;
 255:     }
 256:     const result = await executeSingleTool(call, tools, context, askUser, hooks);
 257:     results.push(result);
 258:   }
 259: 
 260:   return results;
 261: }
 262: 
 263: async function executeSingleTool(
 264:   toolCall: ToolCall,
 265:   tools: Tool[],
 266:   context: ToolContext,
 267:   askUser: AskUserFn,
 268:   hooks?: HookRunner,
 269: ): Promise<ToolExecutionResult> {
 270:   const tool = tools.find((t) => t.name === toolCall.function.name);
 271: 
 272:   if (!tool) {
 273:     return {
 274:       toolName: toolCall.function.name,
 275:       error: `Unknown tool: ${toolCall.function.name}`,
 276:       formatted: `Error: Tool "${toolCall.function.name}" is not available.`,
 277:     };
 278:   }
 279: 
 280:   try {
 281:     let input: Record<string, unknown>;
 282:     try {
 283:       input = JSON.parse(toolCall.function.arguments);
 284:     } catch {
 285:       return {
 286:         toolName: tool.name,
 287:         error: "Invalid JSON arguments",
 288:         formatted: `Error: Failed to parse arguments for ${tool.name}`,
 289:       };
 290:     }
 291: 
 292:     // === PreToolUse hook (before permission + side effects) ===
 293:     if (hooks) {
 294:       const pre = await hooks.runPre({ toolName: tool.name, input });
 295:       if (pre.block) {
 296:         const reason = pre.reason ?? "blocked by hook";
 297:         return {
 298:           toolName: tool.name,
 299:           error: reason,
 300:           formatted: `工具被 hook 拦截: ${reason}`,
 301:         };
 302:       }
 303:       if (pre.input) input = pre.input;
 304:     }
 305: 
 306:     // === Permission check (before any side effect) ===
 307:     const permission = await checkPermission(tool, input, context, {
 308:       askUser,
 309:     });
 310:     if (!permission.allowed) {
 311:       const reason = permission.reason ?? "denied by permission policy";
 312:       return {
 313:         toolName: tool.name,
 314:         error: reason,
 315:         formatted: `权限被拒绝: ${reason}`,
 316:       };
 317:     }
 318: 
 319:     const startTime = Date.now();
 320:     let result = await tool.call(input, context);
 321:     const duration = Date.now() - startTime;
 322: 
 323:     // === PostToolUse hook (may rewrite the result) ===
 324:     if (hooks) {
 325:       const post = await hooks.runPost({ toolName: tool.name, input, result });
 326:       if (post.result) result = post.result;
 327:     }
 328: 
 329:     return {
 330:       toolName: tool.name,
 331:       result,
 332:       formatted: tool.formatResult({
 333:         ...result,
 334:         metadata: { ...result.metadata, durationMs: duration },
 335:       }),
 336:       durationMs: duration,
 337:     };
 338:   } catch (error) {
 339:     const message = error instanceof Error ? error.message : String(error);
 340:     return {
 341:       toolName: tool.name,
 342:       error: message,
 343:       formatted: `Error executing ${tool.name}: ${message}`,
 344:     };
 345:   }
 346: }
