 348: // --- Token Estimation (Simple Heuristic) ---
 349: 
 350: function estimateTokens(messages: Message[]): number {
 351:   let total = 0;
 352:   for (const msg of messages) {
 353:     switch (msg.role) {
 354:       case "user":
 355:         for (const block of msg.content) {
 356:           if (block.type === "text") total += block.text.length;
 357:         }
 358:         break;
 359:       case "assistant":
 360:         if (msg.content) total += msg.content.length;
 361:         if (msg.tool_calls) {
 362:           for (const tc of msg.tool_calls) {
 363:             total += tc.function.arguments.length + tc.function.name.length;
 364:           }
 365:         }
 366:         break;
 367:       case "tool":
 368:         total += msg.content.length;
 369:         break;
 370:       case "system":
 371:         total += msg.content.length;
 372:         break;
 373:     }
 374:   }
 375:   // Rough estimate: ~1 token per 4 characters
 376:   return Math.ceil(total / 4);
 377: }
 378: 
 379: // --- Auto-Compaction ---
 380: 
 381: /**
 382:  * Choose a split point so the retained tail never begins with an orphan tool
 383:  * result. Starts at `messages.length - tailSize` and walks the boundary
 384:  * earlier while the first tail message is a tool result (whose originating
 385:  * assistant message would otherwise be stranded in the summarized half).
 386:  * Returns an index into `messages` (the start of the tail).
 387:  */
 388: function findSafeSplitIndex(messages: Message[], tailSize: number): number {
 389:   let split = Math.max(0, messages.length - tailSize);
 390:   while (split > 0 && messages[split]?.role === "tool") {
 391:     split--;
 392:   }
 393:   return split;
 394: }
 395: 
 396: export async function autoCompact(
 397:   messages: Message[],
 398:   callModel: ModelCaller,
 399:   modelConfig: ModelConfig,
 400: ): Promise<Message[]> {
 401:   const TAIL_SIZE = 20;
 402:   // Find a safe split point. Slicing at a fixed offset can leave the tail
 403:   // starting with an orphan tool result whose assistant (with tool_calls)
 404:   // landed in oldMessages — the provider rejects that ("tool message must
 405:   // follow tool_calls"). Move the boundary earlier until the tail no longer
 406:   // begins with a tool message.
 407:   const splitIndex = findSafeSplitIndex(messages, TAIL_SIZE);
 408: 
 409:   const oldMessages = messages.slice(0, splitIndex);
 410:   const tailMessages = messages.slice(splitIndex);
 411: 
 412:   if (oldMessages.length === 0) return messages;
 413: 
 414:   // Summarize old messages
 415:   const summaryPrompt = `Summarize the conversation so far. Include:
 416: 1. What the user asked for (the main task)
 417: 2. Key decisions made
 418: 3. Files that were modified (with paths)
 419: 4. What still needs to be done
 420: 5. Any important context for continuing the work
 421: 
 422: Be concise but complete. This summary will replace the old messages
 423: so the conversation can continue with a fresh context window.`;
 424: 
 425:   const summaryMessages: Message[] = [
 426:     ...oldMessages,
 427:     { role: "user", content: [{ type: "text", text: summaryPrompt }] },
 428:   ];
 429: 
 430:   // Call model without tools for summarization
 431:   const chunks: string[] = [];
 432:   for await (const event of callModel(
 433:     summaryMessages,
 434:     [],
 435:     "You are a helpful assistant that summarizes conversations.",
 436:     modelConfig,
 437:   )) {
 438:     if (event.type === "text_delta") {
 439:       chunks.push(event.delta);
 440:     }
 441:   }
 442:   const summary = chunks.join("");
 443: 
 444:   // Rebuild: system summary + tail
 445:   return [
 446:     {
 447:       role: "system",
 448:       content: `[CONVERSATION SUMMARY]\n${summary}`,
 449:     },
 450:     ...tailMessages,
 451:   ];
 452: }
 453: 
 454: // --- Error Recovery ---
 455: 
 456: async function handleModelError(
 457:   error: unknown,
 458:   _messages: Message[],
 459:   _callModel: ModelCaller,
 460:   _modelConfig: ModelConfig,
 461: ): Promise<"retry" | "abort"> {
 462:   const err = error as any;
 463: 
 464:   // Rate limit → wait and retry
 465:   if (err?.status === 429) {
 466:     const delay = err?.retryAfter || 5000;
 467:     await sleep(delay);
 468:     return "retry";
 469:   }
 470: 
 471:   // Context too long → compact and retry
 472:   if (
 473:     err?.status === 400 &&
 474:     (err?.message?.includes("context_length") ||
 475:       err?.message?.includes("maximum context"))
 476:   ) {
 477:     return "retry";
 478:   }
 479: 
 480:   // Auth error → abort
 481:   if (err?.status === 401 || err?.status === 403) {
 482:     return "abort";
 483:   }
 484: 
 485:   // Unknown error → abort
 486:   return "abort";
 487: }
 488: 
 489: function sleep(ms: number): Promise<void> {
 490:   return new Promise((resolve) => setTimeout(resolve, ms));
 491: }
