   1: // ============================================================
   2: // Permission System — 4 modes + dangerous pattern detection
   3: // ============================================================
   4: 
   5: import * as path from "node:path";
   6: import type { Tool, ToolContext, ToolInput } from "./types.js";
   7: 
   8: // --- Dangerous Pattern Detection ---
   9: 
  10: interface DangerousCheck {
  11:   dangerous: boolean;
  12:   reason?: string;
  13: }
  14: 
  15: export function checkDangerousPattern(
  16:   toolName: string,
  17:   input: Record<string, unknown>,
  18:   workspaceRoot: string,
  19: ): DangerousCheck {
  20:   // Workspace boundary check for file operations
  21:   if (input.filePath && typeof input.filePath === "string") {
  22:     const resolvedWorkspace = path.resolve(workspaceRoot);
  23:     // Resolve the input against the workspace root so relative paths are
  24:     // judged correctly, and an absolute path outside the root is rejected
  25:     // (path.resolve discards the base when the second arg is absolute).
  26:     const resolved = path.resolve(resolvedWorkspace, input.filePath as string);
  27:     if (
  28:       resolved !== resolvedWorkspace &&
  29:       !resolved.startsWith(resolvedWorkspace + path.sep)
  30:     ) {
  31:       return {
  32:         dangerous: true,
  33:         reason: `Path "${input.filePath}" is outside workspace "${workspaceRoot}"`,
  34:       };
  35:     }
  36:   }
  37: 
  38:   // Bash-specific dangerous patterns
  39:   if (toolName === "bash" && input.command && typeof input.command === "string") {
  40:     const cmd = input.command as string;
  41: 
  42:     // Recursive deletion
  43:     if (/\brm\s+.*-r/.test(cmd) || /\brm\s+.*-rf\b/.test(cmd)) {
  44:       return {
  45:         dangerous: true,
  46:         reason: "Command includes recursive deletion (rm -r)",
  47:       };
  48:     }
  49: 
  50:     // Privilege escalation
  51:     if (/\bsudo\b/.test(cmd)) {
  52:       return {
  53:         dangerous: true,
  54:         reason: "Command uses sudo (privilege escalation)",
  55:       };
  56:     }
  57: 
  58:     // Pipe to shell
  59:     if (/(curl|wget).*\|.*(bash|sh|zsh)/.test(cmd)) {
  60:       return {
  61:         dangerous: true,
  62:         reason: "Command pipes downloaded content to a shell",
  63:       };
  64:     }
  65: 
  66:     // Force push
  67:     if (/\bgit\s+push\s+.*--force/.test(cmd)) {
  68:       return {
  69:         dangerous: true,
  70:         reason: "Force pushing to git",
  71:       };
  72:     }
  73: 
  74:     // Hard reset
  75:     if (/\bgit\s+reset\s+--hard/.test(cmd)) {
  76:       return {
  77:         dangerous: true,
  78:         reason: "Git hard reset — this discards changes",
  79:       };
  80:     }
  81: 
  82:     // Disk/filesystem operations
  83:     if (/\b(mkfs|dd|fdisk)\b/.test(cmd)) {
  84:       return {
  85:         dangerous: true,
  86:         reason: "Command includes disk/filesystem operations",
  87:       };
  88:     }
  89:   }
  90: 
  91:   return { dangerous: false };
  92: }
  93: 
  94: // --- Blocked Paths ---
  95: 
  96: const BLOCKED_PATTERNS = [
  97:   /\.ssh\/.*/,
  98:   /\.ssh$/,
  99:   /\/etc\/(passwd|shadow|sudoers)/,
 100:   /\/etc\/ssl\//,
 101:   /\.env$/,
 102:   /\.env\./,
 103:   /credentials\.json$/,
 104:   /\.npmrc$/,
 105:   /\.git\/config$/,
 106:   /\.git\/hooks\//,
 107: ];
 108: 
 109: export function isBlockedPath(filePath: string): boolean {
 110:   return BLOCKED_PATTERNS.some((pattern) => pattern.test(filePath));
 111: }
 112: 
 113: // --- Main Permission Check ---
 114: 
 115: export interface PermissionCheckOptions {
 116:   /** Callback to prompt the user for permission */
 117:   askUser: (
 118:     tool: Tool,
 119:     input: Record<string, unknown>,
 120:     riskHint?: string,
 121:   ) => Promise<boolean>;
 122: }
 123: 
 124: export async function checkPermission(
 125:   tool: Tool,
 126:   input: Record<string, unknown>,
 127:   context: ToolContext,
 128:   options: PermissionCheckOptions,
 129: ): Promise<{ allowed: boolean; reason?: string }> {
 130:   // Step 1: Read-only tools are always allowed
 131:   if (tool.isReadOnly()) {
 132:     return { allowed: true };
 133:   }
 134: 
 135:   // Step 2: Plan mode — never execute destructive tools
 136:   if (context.permissionMode === "plan") {
 137:     return {
 138:       allowed: false,
 139:       reason: `Plan mode: ${tool.name} is a destructive tool. Not executing.`,
 140:     };
 141:   }
 142: 
 143:   // Step 3: Bypass mode — everything is allowed
 144:   if (context.permissionMode === "bypassPermissions") {
 145:     return { allowed: true };
 146:   }
 147: 
 148:   // Step 4: Check blocked paths
 149:   if (input.filePath && typeof input.filePath === "string") {
 150:     if (isBlockedPath(input.filePath as string)) {
 151:       return {
 152:         allowed: false,
 153:         reason: `Path "${input.filePath}" is blocked for security reasons.`,
 154:       };
 155:     }
 156:   }
 157: 
 158:   // Step 5: Dangerous patterns — ALWAYS require confirmation
 159:   const dangerousCheck = checkDangerousPattern(
 160:     tool.name,
 161:     input,
 162:     context.workspaceRoot,
 163:   );
 164:   if (dangerousCheck.dangerous) {
 165:     const allowed = await options.askUser(tool, input, dangerousCheck.reason);
 166:     return allowed
 167:       ? { allowed: true }
 168:       : { allowed: false, reason: dangerousCheck.reason };
 169:   }
 170: 
 171:   // Step 6: acceptEdits — auto-approve file operations
 172:   if (context.permissionMode === "acceptEdits") {
 173:     if (["edit", "write"].includes(tool.name)) {
 174:       return { allowed: true };
 175:     }
 176:   }
 177: 
 178:   // Step 7: Default — ask only for tools that require interactive approval
 179:   const needsApproval = tool.requiresApproval
 180:     ? tool.requiresApproval()
 181:     : !tool.isReadOnly();
 182:   if (!needsApproval) {
 183:     return { allowed: true };
 184:   }
 185: 
 186:   const allowed = await options.askUser(tool, input);
 187:   return allowed
 188:     ? { allowed: true }
 189:     : { allowed: false, reason: "User denied permission" };
 190: }
