   1: // ============================================================
   2: // Multi-Provider LLM Client Adapter
   3: // ============================================================
   4: 
   5: import OpenAI from "openai";
   6: import { anthropicCaller } from "./anthropic-adapter.js";
   7: import type {
   8:   Message,
   9:   ModelCaller,
  10:   ModelConfig,
  11:   StreamEvent,
  12:   Tool,
  13: } from "./types.js";
  14: 
  15: // --- Provider Default Configurations ---
  16: 
  17: const PROVIDER_CONFIGS: Record<
  18:   string,
  19:   { baseURL: string; defaultModel: string }
  20: > = {
  21:   anthropic: {
  22:     baseURL: "https://api.anthropic.com",
  23:     defaultModel: "claude-opus-4-8",
  24:   },
  25:   openai: {
  26:     baseURL: "https://api.openai.com/v1",
  27:     defaultModel: "gpt-4o",
  28:   },
  29:   deepseek: {
  30:     baseURL: "https://api.deepseek.com/v1",
  31:     defaultModel: "deepseek-chat",
  32:   },
  33:   qwen: {
  34:     baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
  35:     defaultModel: "qwen-plus",
  36:   },
  37:   moonshot: {
  38:     baseURL: "https://api.moonshot.cn/v1",
  39:     defaultModel: "moonshot-v1-128k",
  40:   },
  41:   zhipu: {
  42:     baseURL: "https://open.bigmodel.cn/api/paas/v4",
  43:     defaultModel: "glm-4",
  44:   },
  45:   custom: {
  46:     baseURL: "http://localhost:11434/v1",
  47:     defaultModel: "llama3",
  48:   },
  49: };
  50: 
  51: // --- Message Conversion (Internal → OpenAI) ---
  52: 
  53: function convertToOpenAIMessage(
  54:   msg: Message,
  55: ): OpenAI.Chat.Completions.ChatCompletionMessageParam {
  56:   switch (msg.role) {
  57:     case "user":
  58:       return {
  59:         role: "user",
  60:         content: msg.content.map((block) => {
  61:           if (block.type === "text") {
  62:             return { type: "text", text: block.text } as const;
  63:           }
  64:           if (block.type === "image") {
  65:             const url =
  66:               block.source.type === "base64"
  67:                 ? `data:${block.source.media_type};base64,${block.source.data}`
  68:                 : block.source.url!;
  69:             return {
  70:               type: "image_url",
  71:               image_url: { url },
  72:             } as const;
  73:           }
  74:           throw new Error(`Unknown content type: ${(block as any).type}`);
  75:         }),
  76:       };
  77: 
  78:     case "assistant":
  79:       return {
  80:         role: "assistant",
  81:         content: msg.content,
  82:         tool_calls: msg.tool_calls as any,
  83:       };
  84: 
  85:     case "tool":
  86:       return {
  87:         role: "tool",
  88:         tool_call_id: msg.tool_call_id,
  89:         content: msg.content,
  90:       };
  91: 
  92:     case "system":
  93:       return {
  94:         role: "system",
  95:         content: msg.content,
  96:       };
  97:   }
  98: }
  99: 
 100: // --- OpenAI-Compatible Streaming Caller ---
 101: 
 102: async function* openAICompatibleCaller(
 103:   messages: Message[],
 104:   tools: Tool[],
 105:   systemPrompt: string,
 106:   config: ModelConfig,
 107: ): AsyncGenerator<StreamEvent> {
 108:   const client = new OpenAI({
 109:     apiKey: config.apiKey,
 110:     baseURL:
 111:       config.baseURL ||
 112:       PROVIDER_CONFIGS[config.provider]?.baseURL ||
 113:       "https://api.openai.com/v1",
 114:   });
 115: 
 116:   const model =
 117:     config.model || PROVIDER_CONFIGS[config.provider]?.defaultModel || "gpt-4o";
 118: 
 119:   const requestMessages: OpenAI.Chat.Completions.ChatCompletionMessageParam[] =
 120:     [
 121:       { role: "system", content: systemPrompt },
 122:       ...messages.map(convertToOpenAIMessage),
 123:     ];
 124: 
 125:   const stream = await client.chat.completions.create({
 126:     model,
 127:     messages: requestMessages,
 128:     tools: tools.length > 0 ? formatToolsForOpenAI(tools) : undefined,
 129:     tool_choice: tools.length > 0 ? "auto" : undefined,
 130:     max_tokens: config.maxTokens,
 131:     temperature: config.temperature ?? 0.1,
 132:     stream: true,
 133:     // Ask the provider to emit a final usage chunk. Without this, streamed
 134:     // responses carry no token counts and usage stays at zero — breaking
 135:     // both the CLI token display and the auto-compaction threshold.
 136:     stream_options: { include_usage: true },
 137:   });
 138: 
 139:   // Parse streaming response
 140:   const toolCallBuffers: Map<
 141:     number,
 142:     { id: string; name: string; arguments: string }
 143:   > = new Map();
 144: 
 145:   let usage = { input_tokens: 0, output_tokens: 0 };
 146:   let finishReason = "stop";
 147:   let toolCallsEmitted = false;
 148: 
 149:   const emitToolCalls = function* (): Generator<StreamEvent> {
 150:     if (toolCallsEmitted) return;
 151:     toolCallsEmitted = true;
 152:     for (const [, buf] of toolCallBuffers) {
 153:       try {
 154:         const input = JSON.parse(buf.arguments);
 155:         yield { type: "tool_use", id: buf.id, name: buf.name, input };
 156:       } catch {
 157:         yield {
 158:           type: "error",
 159:           error: new Error(
 160:             `Failed to parse tool arguments for "${buf.name}"`,
 161:           ),
 162:         };
 163:       }
 164:     }
 165:   };
 166: 
 167:   for await (const chunk of stream) {
 168:     const delta = chunk.choices[0]?.delta;
 169: 
 170:     // Text delta
 171:     if (delta?.content) {
 172:       yield { type: "text_delta", delta: delta.content };
 173:     }
 174: 
 175:     // Tool call delta
 176:     if (delta?.tool_calls) {
 177:       for (const tc of delta.tool_calls) {
 178:         if (!toolCallBuffers.has(tc.index)) {
 179:           toolCallBuffers.set(tc.index, {
 180:             id: tc.id || "",
 181:             name: tc.function?.name || "",
 182:             arguments: "",
 183:           });
 184:         }
 185:         const buf = toolCallBuffers.get(tc.index)!;
 186:         if (tc.id) buf.id = tc.id;
 187:         if (tc.function?.name) buf.name = tc.function.name;
 188:         if (tc.function?.arguments) buf.arguments += tc.function.arguments;
 189:       }
 190:     }
 191: 
 192:     // Usage — with stream_options.include_usage this arrives in a final
 193:     // chunk whose `choices` array is empty, AFTER the finish_reason chunk.
 194:     if (chunk.usage) {
 195:       usage = {
 196:         input_tokens: chunk.usage.prompt_tokens || 0,
 197:         output_tokens: chunk.usage.completion_tokens || 0,
 198:       };
 199:     }
 200: 
 201:     // Finish reason — emit completed tool calls now, but defer the `done`
 202:     // event until the stream fully drains so the usage chunk is included.
 203:     if (chunk.choices[0]?.finish_reason) {
 204:       finishReason = chunk.choices[0].finish_reason;
 205:       yield* emitToolCalls();
 206:     }
 207:   }
 208: 
 209:   // Stream drained — emit tool calls if finish_reason never fired, then done.
 210:   yield* emitToolCalls();
 211:   yield { type: "done", usage, finish_reason: finishReason };
 212: }
 213: 
 214: // --- Format Tools for OpenAI ---
 215: 
 216: function formatToolsForOpenAI(tools: Tool[]): OpenAI.Chat.Completions.ChatCompletionTool[] {
 217:   return tools
 218:     .filter((t) => t.isEnabled())
 219:     .map((t) => ({
 220:       type: "function" as const,
 221:       function: {
 222:         name: t.name,
 223:         description: t.promptDescription,
 224:         parameters: t.inputSchema,
 225:       },
 226:     }));
 227: }
 228: 
 229: // --- Model Caller Factory ---
 230: 
 231: export function createModelCaller(cfg: ModelConfig): ModelCaller {
 232:   if (cfg.provider === "anthropic") {
 233:     return anthropicCaller;
 234:   }
 235:   // All non-Anthropic providers use OpenAI-compatible API for now.
 236:   return openAICompatibleCaller;
 237: }
 238: 
 239: // --- Error Detection Helpers ---
 240: 
 241: export function isRateLimitError(error: any): boolean {
 242:   return error?.status === 429;
 243: }
 244: 
 245: export function isContextLengthError(error: any): boolean {
 246:   return (
 247:     error?.status === 400 &&
 248:     (error?.message?.includes("context_length") ||
 249:       error?.message?.includes("maximum context"))
 250:   );
 251: }
 252: 
 253: export function isAuthError(error: any): boolean {
 254:   return error?.status === 401 || error?.status === 403;
 255: }
 256: 
 257: export function isProviderError(error: any): boolean {
 258:   return error?.status >= 500;
 259: }
 260: 
 261: // --- Provider Resolution ---
 262: 
 263: export function resolveProviderConfig(
 264:   partial: Partial<ModelConfig> & { apiKey: string },
 265: ): ModelConfig {
 266:   const provider = partial.provider || "openai";
 267:   const defaults = PROVIDER_CONFIGS[provider] || PROVIDER_CONFIGS.custom;
 268: 
 269:   return {
 270:     provider,
 271:     model: partial.model || defaults.defaultModel,
 272:     apiKey: partial.apiKey,
 273:     baseURL: partial.baseURL || defaults.baseURL,
 274:     maxTokens: partial.maxTokens,
 275:     temperature: partial.temperature,
 276:     options: partial.options,
 277:   };
 278: }
 279: 
 280: export { PROVIDER_CONFIGS };
