   2: // System Prompt Builder — 6 static sections + dynamic boundary
   3: // ============================================================
   4: 
   5: import type { Tool } from "./types.js";
   6: 
   7: /**
   8:  * Section 1: Identity Declaration
   9:  */
  10: function buildIdentitySection(): string {
  11:   return `You are an interactive AI coding assistant. You help users with software
  12: engineering tasks including code analysis, debugging, refactoring, writing
  13: new code, and explaining technical concepts.
  14: 
  15: SECURITY: Never suggest or execute commands that install malware, exfiltrate
  16: data, or compromise system security. When asked to run suspicious commands,
  17: explain the risk and refuse unless the user explicitly and knowingly approves
  18: the dangerous operation.`;
  19: }
  20: 
  21: /**
  22:  * Section 2: Workspace Information (Dynamic)
  23:  */
  24: function buildWorkspaceSection(workspaceRoot: string): string {
  25:   const date = new Date().toISOString().split("T")[0];
  26:   return `OS Version: ${process.platform} ${process.env.OS || ""}
  27: Shell: ${process.env.SHELL || process.env.ComSpec || "unknown"}
  28: Workspace Folder: ${workspaceRoot}
  29: Current date: ${date}
  30: 
  31: Note: Prefer absolute paths over relative paths. Use the workspace root
  32: as the base for all file operations unless the user specifies otherwise.`;
  33: }
  34: 
  35: /**
  36:  * Section 3: Coding Rules
  37:  */
  38: function buildCodingRulesSection(): string {
  39:   return `CODING RULES:
  40: 
  41: - ALWAYS read a file before editing it using the Read tool (unless you've
  42:   just read it in the current conversation).
  43: - Use the Edit tool for precise changes. NEVER rewrite an entire large file
  44:   unless absolutely necessary. Edit uses search/replace — the old_string
  45:   must match exactly including whitespace and indentation.
  46: - Keep code concise. Do not add unnecessary comments, error handling,
  47:   validations, or features that the user did not request.
  48: - Do not abstract prematurely. Follow YAGNI (You Aren't Gonna Need It).
  49: - Prefer editing existing files over creating new ones.
  50: - Batch independent operations: use parallel tool calls whenever possible.
  51: - If a tool call fails due to non-unique match, add more context lines
  52:   to make the old_string unique.`;
  53: }
  54: 
  55: /**
  56:  * Section 4: Tool Usage Rules
  57:  */
  58: function buildToolUsageSection(): string {
  59:   return `USING YOUR TOOLS:
  60: 
  61: - PREFER dedicated tools (Read, Edit, Write, Glob, Grep) over Bash for
  62:   file operations. Tools are safer, faster, and more reliable.
  63: - Use Glob to find files by name pattern (e.g., "src/**/*.ts").
  64: - Use Grep to search file contents with regex patterns.
  65: - Use Bash ONLY for: running build/test commands, git operations,
  66:   package managers (npm, pip, cargo), and other CLI tasks that don't
  67:   have a dedicated tool.
  68: - When using Bash: commands must be non-interactive (no stdin prompts).
  69:   Add --yes or equivalent flags for package managers.
  70: - Call independent tools in PARALLEL for maximum efficiency.
  71:   Example: reading 3 files → 3 simultaneous Read calls.
  72:   Example: Grep + Glob → parallel calls.`;
  73: }
  74: 
  75: /**
  76:  * Section 5: Output Style
  77:  */
  78: function buildOutputStyleSection(): string {
  79:   return `OUTPUT STYLE:
  80: 
  81: - Be concise and direct. Get to the point quickly.
  82: - Do not add narration inside code blocks just to explain what the code does.
  83: - Use the following format when citing code:
  84:   \`\`\`startLine:endLine:filepath
  85: - Respond in the same language as the user's query.
  86:   If the user writes in Chinese, respond in Chinese.
  87: - Minimize output tokens while maintaining quality.`;
  88: }
  89: 
  90: /**
  91:  * Section 6: Destructive Actions
  92:  */
  93: function buildDestructiveActionsSection(): string {
  94:   return `DESTRUCTIVE ACTIONS:
  95: 
  96: Before performing potentially destructive actions, consider:
  97: - Is this reversible? Can the user undo easily?
  98: - What is the blast radius? How many things could break?
  99: - Does this affect files outside the workspace?
 100: 
 101: The following ALWAYS require explicit user confirmation:
 102: - Deleting files or directories (rm, del, etc.)
 103: - Force-pushing to git (git push --force)
 104: - Database modifications (DROP, DELETE, TRUNCATE)
 105: - Installing packages that execute postinstall scripts
 106: - Running commands that pipe downloaded content to a shell (curl|bash)`;
 107: }
 108: 
 109: /**
 110:  * Build tool descriptions for system prompt
 111:  */
 112: function buildToolDescriptionsSection(tools: Tool[]): string {
 113:   const lines = ["AVAILABLE TOOLS:", ""];
 114:   for (const tool of tools) {
 115:     if (!tool.isEnabled()) continue;
 116:     lines.push(
 117:       `${tool.name} — ${tool.promptDescription}`,
 118:       `  Parameters: ${JSON.stringify(tool.inputSchema.properties)}`,
 119:       "",
 120:     );
 121:   }
 122:   return lines.join("\n");
 123: }
 124: 
 125: /**
 126:  * Dynamic boundary marker
 127:  */
 128: export const DYNAMIC_BOUNDARY =
 129:   "--- SYSTEM PROMPT DYNAMIC BOUNDARY ---\n" +
 130:   "Everything below this line is session/user-specific and cannot be cached.";
 131: 
 132: export interface SystemPromptOptions {
 133:   workspaceRoot: string;
 134:   tools: Tool[];
 135:   /** Content of CLAUDE.md from workspace root */
 136:   claudeMdContent?: string;
 137:   /** Git status info */
 138:   gitStatus?: string;
 139:   /** Language preference detected from user */
 140:   languagePreference?: string;
 141: }
 142: 
 143: /**
 144:  * Build the complete system prompt as an array of strings.
 145:  * Join with "\n\n" at the end for sending to the LLM.
 146:  */
 147: export function buildSystemPrompt(options: SystemPromptOptions): string {
 148:   const staticSections = [
 149:     buildIdentitySection(),
 150:     buildWorkspaceSection(options.workspaceRoot),
 151:     buildCodingRulesSection(),
 152:     buildToolUsageSection(),
 153:     buildOutputStyleSection(),
 154:     buildDestructiveActionsSection(),
 155:     buildToolDescriptionsSection(options.tools),
 156:   ];
 157: 
 158:   const dynamicSections: string[] = [DYNAMIC_BOUNDARY];
 159: 
 160:   // User context from CLAUDE.md
 161:   if (options.claudeMdContent) {
 162:     dynamicSections.push(
 163:       `[PROJECT CONTEXT from CLAUDE.md]\n${options.claudeMdContent}`,
 164:     );
 165:   }
 166: 
 167:   // Git status
 168:   if (options.gitStatus) {
 169:     dynamicSections.push(`[GIT STATUS]\n${options.gitStatus}`);
 170:   }
 171: 
 172:   // Language preference
 173:   if (options.languagePreference) {
 174:     dynamicSections.push(
 175:       `[LANGUAGE PREFERENCE]\nThe user prefers responses in: ${options.languagePreference}`,
 176:     );
 177:   }
 178: 
 179:   return [...staticSections, ...dynamicSections].join("\n\n");
 180: }
 181: 
 182: /**
 183:  * Rebuild only dynamic sections without changing static sections.
 184:  * Static sections are cached between requests.
 185:  */
 186: export function rebuildDynamicSections(
 187:   currentPrompt: string,
 188:   dynamicOptions: Pick<
 189:     SystemPromptOptions,
 190:     "claudeMdContent" | "gitStatus" | "languagePreference"
 191:   >,
 192: ): string {
 193:   const boundaryIndex = currentPrompt.indexOf(DYNAMIC_BOUNDARY);
 194:   if (boundaryIndex === -1) {
 195:     // No boundary found, rebuild entirely
 196:     return currentPrompt;
 197:   }
 198: 
 199:   const staticPart = currentPrompt.slice(0, boundaryIndex);
 200:   const dynamicSections: string[] = [DYNAMIC_BOUNDARY];
 201: 
 202:   if (dynamicOptions.claudeMdContent) {
 203:     dynamicSections.push(
 204:       `[PROJECT CONTEXT from CLAUDE.md]\n${dynamicOptions.claudeMdContent}`,
 205:     );
 206:   }
 207:   if (dynamicOptions.gitStatus) {
 208:     dynamicSections.push(`[GIT STATUS]\n${dynamicOptions.gitStatus}`);
 209:   }
 210:   if (dynamicOptions.languagePreference) {
 211:     dynamicSections.push(
 212:       `[LANGUAGE PREFERENCE]\nThe user prefers responses in: ${dynamicOptions.languagePreference}`,
 213:     );
 214:   }
 215: 
 216:   return staticPart + dynamicSections.join("\n\n");
 217: }
