   1: // ============================================================
   2: // Core Types for Claude Code Replica
   3: // ============================================================
   4: 
   5: // --- Messages (Internal Format) ---
   6: 
   7: export type Message =
   8:   | UserMessage
   9:   | AssistantMessage
  10:   | ToolResultMessage
  11:   | SystemMessage;
  12: 
  13: export interface UserMessage {
  14:   role: "user";
  15:   content: ContentBlock[];
  16: }
  17: 
  18: export interface AssistantMessage {
  19:   role: "assistant";
  20:   content: string | null;
  21:   tool_calls?: ToolCall[];
  22: }
  23: 
  24: export interface ToolResultMessage {
  25:   role: "tool";
  26:   tool_call_id: string;
  27:   name?: string;
  28:   content: string;
  29: }
  30: 
  31: export interface SystemMessage {
  32:   role: "system";
  33:   content: string;
  34: }
  35: 
  36: // --- Content Blocks ---
  37: 
  38: export type ContentBlock = TextContent | ImageContent;
  39: 
  40: export interface TextContent {
  41:   type: "text";
  42:   text: string;
  43: }
  44: 
  45: export interface ImageContent {
  46:   type: "image";
  47:   source: {
  48:     type: "base64" | "url";
  49:     media_type: string;
  50:     data?: string;
  51:     url?: string;
  52:   };
  53: }
  54: 
  55: // --- Tool Calls ---
  56: 
  57: export interface ToolCall {
  58:   id: string;
  59:   type: "function";
  60:   function: {
  61:     name: string;
  62:     arguments: string; // JSON string
  63:   };
  64: }
  65: 
  66: // --- Tool System ---
  67: 
  68: export interface ToolInput {
  69:   [key: string]: unknown;
  70: }
  71: 
  72: export interface ToolResult {
  73:   content: string;
  74:   error?: string;
  75:   truncated?: boolean;
  76:   metadata?: ToolResultMetadata;
  77:   /**
  78:    * Optional image blocks produced by the tool (e.g. Read on a PNG/PDF).
  79:    * The agent loop injects these into the conversation as a follow-up user
  80:    * message, since both providers accept images only in user content.
  81:    */
  82:   images?: ImageContent[];
  83: }
  84: 
  85: export interface ToolResultMetadata {
  86:   durationMs?: number;
  87:   linesRead?: number;
  88:   fileSize?: number;
  89:   exitCode?: number;
  90: }
  91: 
  92: export interface ToolContext {
  93:   workspaceRoot: string;
  94:   sessionId: string;
  95:   permissionMode: PermissionMode;
  96:   /** Optional: model config for sub-agents (Task tool) */
  97:   modelConfig?: ModelConfig;
  98:   /** Optional sink for nested sub-agent activity (Task tool). */
  99:   onSubAgentProgress?: (event: SubAgentProgress) => void;
 100: }
 101: 
 102: export interface SubAgentProgress {
 103:   subagentName: string;
 104:   phase: "tool_use" | "tool_results" | "done";
 105:   toolName?: string;
 106:   input?: Record<string, unknown>;
 107:   results?: ToolExecutionResult[];
 108: }
 109: 
 110: export type PermissionMode =
 111:   | "default"
 112:   | "acceptEdits"
 113:   | "bypassPermissions"
 114:   | "plan";
 115: 
 116: export type PermissionResult =
 117:   | { allowed: true }
 118:   | { allowed: false; reason: string };
 119: 
 120: export interface Tool<T extends ToolInput = ToolInput> {
 121:   /** Unique tool name */
 122:   name: string;
 123:   /** Human-readable description */
 124:   description: string;
 125:   /** Description for the LLM system prompt */
 126:   promptDescription: string;
 127:   /** JSON Schema for input validation */
 128:   inputSchema: {
 129:     type: "object";
 130:     properties: Record<
 131:       string,
 132:       {
 133:         type: string;
 134:         description?: string;
 135:         enum?: string[];
 136:         default?: unknown;
 137:         /** For array properties: the schema of each item. */
 138:         items?: Record<string, unknown>;
 139:         [key: string]: unknown;
 140:       }
 141:     >;
 142:     required: string[];
 143:   };
 144:   /** Whether this tool is currently enabled */
 145:   isEnabled(): boolean;
 146:   /** Whether this tool only reads (auto-approved) */
 147:   isReadOnly(): boolean;
 148:   /** Whether this tool requires an interactive approval prompt in default mode. */
 149:   requiresApproval?(): boolean;
 150:   /** Whether this tool can run concurrently */
 151:   isConcurrencySafe(): boolean;
 152:   /** Main execution */
 153:   call(input: T, context: ToolContext): Promise<ToolResult>;
 154:   /** Permission check */
 155:   checkPermissions(
 156:     input: T,
 157:     context: ToolContext,
 158:   ): Promise<PermissionResult>;
 159:   /** Format result for LLM */
 160:   formatResult(result: ToolResult): string;
 161: }
 162: 
 163: // --- Model Config ---
 164: 
 165: export interface ModelConfig {
 166:   provider: "anthropic" | "openai" | "deepseek" | "qwen" | "moonshot" | "zhipu" | "custom";
 167:   model: string;
 168:   apiKey: string;
 169:   baseURL?: string;
 170:   maxTokens?: number;
 171:   temperature?: number;
 172:   options?: Record<string, unknown>;
 173: }
 174: 
 175: // --- Stream Events ---
 176: 
 177: export type StreamEvent =
 178:   | { type: "text_delta"; delta: string }
 179:   | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 180:   | { type: "thinking"; delta?: string }
 181:   | {
 182:       type: "done";
 183:       usage: { input_tokens: number; output_tokens: number };
 184:       finish_reason: string;
 185:     }
 186:   | { type: "error"; error: Error };
 187: 
 188: // --- Agent Loop ---
 189: 
 190: export type LoopEvent =
 191:   | { type: "text_delta"; delta: string }
 192:   | { type: "tool_use"; name: string; input: Record<string, unknown> }
 193:   | { type: "tool_results"; results: ToolExecutionResult[] }
 194:   | { type: "thinking" }
 195:   | { type: "compacting" }
 196:   | { type: "compacted"; summary: string }
 197:   | {
 198:       type: "usage";
 199:       usage: { input_tokens: number; output_tokens: number };
 200:     }
 201:   | { type: "error"; error: unknown }
 202:   | {
 203:       type: "done";
 204:       finishReason: "end_turn" | "max_turns";
 205:       turns: number;
 206:       message?: string;
 207:     }
 208:   | { type: "aborted"; reason: string };
 209: 
 210: export interface ToolExecutionResult {
 211:   toolName: string;
 212:   result?: ToolResult;
 213:   error?: string;
 214:   formatted: string;
 215:   durationMs?: number;
 216: }
 217: 
 218: export interface LoopOptions {
 219:   maxTurns?: number;
 220:   autoCompactThreshold?: number;
 221:   systemPrompt: string;
 222:   abortSignal?: AbortSignal;
 223:   /** Partial context to thread into each tool call (sessionId, workspaceRoot, permissionMode). */
 224:   toolContext?: Partial<ToolContext>;
 225:   /** Callback to prompt the user when a tool requires confirmation. */
 226:   askUser?: AskUserFn;
 227:   /** Optional hook registry to intercept tool calls (PreToolUse/PostToolUse). */
 228:   hooks?: HookRunner;
 229: }
 230: 
 231: /** Structural type for the hook registry — see src/hooks.ts. */
 232: export interface HookRunner {
 233:   runPre(payload: {
 234:     toolName: string;
 235:     input: Record<string, unknown>;
 236:   }): Promise<{
 237:     block?: boolean;
 238:     reason?: string;
 239:     input?: Record<string, unknown>;
 240:   }>;
 241:   runPost(payload: {
 242:     toolName: string;
 243:     input: Record<string, unknown>;
 244:     result: ToolResult;
 245:   }): Promise<{ result?: ToolResult }>;
 246: }
 247: 
 248: /** Prompts the user to approve a destructive/dangerous tool call. */
 249: export type AskUserFn = (
 250:   tool: Tool,
 251:   input: Record<string, unknown>,
 252:   riskHint?: string,
 253: ) => Promise<boolean>;
 254: 
 255: // --- Model Caller ---
 256: 
 257: export type ModelCaller = (
 258:   messages: Message[],
 259:   tools: Tool[],
 260:   systemPrompt: string,
 261:   config: ModelConfig,
 262: ) => AsyncGenerator<StreamEvent>;
