  62:     apiKey,
  63:     model: process.env.LLM_MODEL || undefined,
  64:     baseURL: process.env.LLM_BASE_URL || undefined,
  65:     maxTokens: process.env.LLM_MAX_TOKENS
  66:       ? parseInt(process.env.LLM_MAX_TOKENS)
  67:       : undefined,
  68:     temperature: process.env.LLM_TEMPERATURE
  69:       ? parseFloat(process.env.LLM_TEMPERATURE)
  70:       : undefined,
  71:   });
  72: }
