  74: // --- Workspace ---
  75: 
  76: function getWorkspaceRoot(): string {
  77:   return process.env.WORKSPACE_ROOT || process.cwd();
  78: }
  79: 
  80: const VALID_PERMISSION_MODES: PermissionMode[] = [
  81:   "default",
  82:   "acceptEdits",
  83:   "bypassPermissions",
  84:   "plan",
  85: ];
  86: 
  87: function getPermissionMode(): PermissionMode {
  88:   const mode = process.env.PERMISSION_MODE as PermissionMode | undefined;
  89:   if (mode && VALID_PERMISSION_MODES.includes(mode)) {
  90:     return mode;
  91:   }
  92:   return "default";
  93: }
  94: 
  95: // --- Load CLAUDE.md ---
  96: 
  97: function loadClaudeMd(workspaceRoot: string): string | undefined {
  98:   const claudeMdPath = path.join(workspaceRoot, "CLAUDE.md");
  99:   try {
 100:     return fs.readFileSync(claudeMdPath, "utf-8");
 101:   } catch {
 102:     return undefined;
 103:   }
