 108: async function main() {
 109:   const verbose = process.argv.includes("--verbose") || process.env.CCR_VERBOSE === "1";
 110:   const quiet = process.argv.includes("--quiet") || process.env.CCR_QUIET === "1" || !verbose;
 111:   const uiState = {
 112:     showTokens:
 113:       process.argv.includes("--show-tokens") ||
 114:       process.env.SHOW_TOKENS === "1" ||
 115:       verbose,
 116:     verbose,
