 118: 
 119:   if (verbose) {
 120:     console.log("╔══════════════════════════════════════╗");
 121:     console.log("║   Claude Code Replica — v1.0.0      ║");
 122:     console.log("║   Local AI Coding Assistant         ║");
 123:     console.log("╚══════════════════════════════════════╝");
 124:     console.log("");
 125:   }
 126: 
 127:   // Load configuration
 128:   const modelConfig = loadConfig();
 129:   const workspaceRoot = getWorkspaceRoot();
 130:   const permissionMode = getPermissionMode();
 131:   const claudeMdContent = loadClaudeMd(workspaceRoot);
