 141:   // --- Persistence ---
 142: 
 143:   const messages: Message[] = [];
 144:   const persistence = new PersistenceManager(workspaceRoot);
 145: 
 146:   // Parse --session from CLI args
 147:   const sessionArg = process.argv.find((a) => a.startsWith("--session="));
 148:   let sessionId = sessionArg?.split("=")[1];
