 152:   if (!sessionId && verbose) {
 153:     const sessions = await persistence.listSessions();
 154:     const incomplete = sessions.filter((s) => !s.completed);
 155:     if (incomplete.length > 0) {
 156:       console.log("Recent incomplete sessions:");
 157:       for (const s of incomplete.slice(0, 5)) {
