 159:           `  ${s.sessionId.slice(0, 8)}... — ${s.messageCount} msgs — ${new Date(s.updatedAt).toLocaleString()}`,
 160:         );
 161:       }
 162:       console.log(
 163:         '  Use --session=<id> to resume, or continue for a new session.',
 164:       );
 165:       console.log("");
 166:     }
 167:   }
