 169:   // Generate or resume session
 170:   if (sessionId) {
 171:     const existing = await persistence.load(sessionId);
 172:     if (existing) {
 173:       messages.push(...existing.messages);
 174:       if (verbose) {
 175:         console.log(
 176:           `Resumed session ${sessionId.slice(0, 8)}... (${existing.messageCount} messages)`,
 177:         );
 178:       }
 179:     } else {
 180:       console.log(
 181:         `Session ${sessionId.slice(0, 8)}... not found. Starting new session.`,
 182:       );
 183:       sessionId = persistence.generateId();
 184:     }
 185:   } else {
 186:     sessionId = persistence.generateId();
 187:   }
 188:   if (verbose) {
 189:     console.log(`Session: ${sessionId.slice(0, 8)}...`);
 190:     console.log("");
 191:   }
 192: 
 193:   // --- Tool Setup ---
 194: 
 195:   const toolRegistry = new ToolRegistry();
 196:   for (const tool of CORE_TOOLS) {
 197:     toolRegistry.register(tool);
 198:   }
 199: 
 200:   // MCP Setup
 201:   const mcpManager = new MCPManager();
 202:   const mcpConfigs = discoverMCPConfigs(workspaceRoot);
 203:   for (const configPath of mcpConfigs) {
 204:     await mcpManager.loadConfig(configPath);
 205:   }
 206:   for (const mcpTool of mcpManager.getAllTools()) {
 207:     toolRegistry.register(mcpTool);
 208:   }
 209: 
 210:   if (verbose) {
 211:     console.log(`Tools loaded: ${toolRegistry.enabledCount}`);
 212:     if (mcpManager.serverCount > 0) {
 213:       console.log(`MCP servers:  ${mcpManager.serverCount}`);
 214:     }
 215:     console.log("");
 216:   }
 217: 
 218:   // --- System Prompt ---
 219: 
 220:   const systemPrompt = buildSystemPrompt({
 221:     workspaceRoot,
 222:     tools: toolRegistry.getEnabledTools(),
 223:     claudeMdContent,
 224:   });
 225: 
 226:   // --- Model Caller ---
 227: 
 228:   const callModel = createModelCaller(modelConfig);
 229: 
 230:   // --- Conversation ---
 231: 
 232:   const tools = toolRegistry.getEnabledTools();
 233: 
 234:   // --- Hooks ---
 235:   // Empty by default. Register PreToolUse/PostToolUse hooks here (or load
 236:   // them from project config) to intercept, block, or rewrite tool calls.
 237:   const hooks = new HookRegistry();
 238: 
 239:   // --- REPL ---
 240: 
 241:   // Interactive (raw-mode) input when attached to a TTY: bordered input box,
 242:   // "/" autocomplete, and selectable permission menus. Otherwise fall back to
 243:   // the line-based readline reader (pipes, CI, non-TTY).
 244:   const isInteractive = Boolean(process.stdin.isTTY && process.stdout.isTTY);
 245: 
 246:   let rl: readline.Interface | null = null;
 247:   let askQuestion: (prompt: string) => Promise<string | null>;
 248:   let readInput: () => Promise<string | null>;
 249:   let closeInput: () => void;
 250: 
 251:   if (isInteractive) {
 252:     const reader = createRawInputReader({
 253:       commands: COMMANDS.map((c) => ({ name: c.name, description: c.description })),
 254:     });
 255:     askQuestion = reader.askQuestion;
 256:     readInput = reader.readInput;
 257:     closeInput = reader.close;
 258:   } else {
 259:     rl = readline.createInterface({
 260:       input: process.stdin,
 261:       output: process.stdout,
 262:     });
 263:     const inputReader = createCliInputReader(rl);
 264:     askQuestion = inputReader.askQuestion;
 265:     readInput = inputReader.readInput;
 266:     closeInput = () => rl?.close();
 267:   }
 268: 
 269:   // Tool+target combos the user chose to "always" allow this session.
 270:   const alwaysAllow = new Set<string>();
 271:   const permissionKey = (toolName: string, input: Record<string, unknown>): string => {
 272:     const target =
 273:       (typeof input.filePath === "string" && input.filePath) ||
 274:       (typeof input.command === "string" && input.command) ||
 275:       (typeof input.url === "string" && input.url) ||
 276:       "";
 277:     return `${toolName}::${target}`;
 278:   };
 279: 
 280:   const resumeSession = async (idOrPrefix: string): Promise<boolean> => {
 281:     const sessions = await persistence.listSessions();
 282:     const matches = sessions.filter((s) => s.sessionId.startsWith(idOrPrefix));
 283:     if (matches.length !== 1) return false;
 284:     const existing = await persistence.load(matches[0].sessionId);
 285:     if (!existing) return false;
 286:     sessionId = existing.sessionId;
 287:     messages.length = 0;
 288:     messages.push(...existing.messages);
 289:     console.log(chalk.gray(`  Resumed session ${sessionId.slice(0, 8)}... (${messages.length} messages)`));
 290:     return true;
 291:   };
 292: 
 293:   const makeCommandContext = () => ({
 294:     messages,
 295:     modelConfig,
 296:     callModel,
 297:     workspaceRoot,
 298:     sessionId: sessionId!,
 299:     persistence,
 300:     ui: uiState,
 301:     permissions: {
 302:       listAlwaysAllow: () => Array.from(alwaysAllow),
 303:       clearAlwaysAllow: () => alwaysAllow.clear(),
 304:     },
 305:     resumeSession,
 306:   });
 307: 
 308:   // Permission prompt callback. On TTY this draws a bordered Yes/No menu;
 309:   // otherwise it prints a text prompt and reads a y/a/n line. The mutex
 310:   // prevents concurrent tool calls from prompting at the same time.
 311:   let permissionPromptChain: Promise<unknown> = Promise.resolve();
 312:   const askUserImpl: AskUserFn = async (tool, input, riskHint) => {
 313:     const key = permissionKey(tool.name, input);
 314:     // Already approved as "always" for this tool+target this session.
 315:     if (alwaysAllow.has(key)) return true;
 316: 
 317:     if (isInteractive) {
 318:       const detail =
 319:         (typeof input.command === "string" && input.command) ||
 320:         (typeof input.filePath === "string" && input.filePath) ||
 321:         (typeof input.url === "string" && input.url) ||
 322:         undefined;
 323:       const choice = await promptPermissionMenu({
 324:         header: `${tool.name[0]!.toUpperCase()}${tool.name.slice(1)} request`,
 325:         detail,
 326:         riskHint,
 327:       });
 328:       if (choice === "always") {
 329:         alwaysAllow.add(key);
 330:         return true;
 331:       }
 332:       return choice === "yes";
 333:     }
 334: 
 335:     renderPermissionPrompt(tool.name, input, riskHint);
 336:     const raw = await askQuestion("     > ");
 337:     // EOF while awaiting a permission decision → treat as deny (safe default).
 338:     if (raw === null) return false;
 339:     const answer = raw.trim().toLowerCase();
 340: 
 341:     if (answer === "a" || answer === "always") {
 342:       alwaysAllow.add(key);
 343:       return true;
 344:     }
 345:     return answer === "y" || answer === "yes";
 346:   };
 347: 
 348:   const askUser: AskUserFn = (tool, input, riskHint) => {
 349:     const run = permissionPromptChain.then(() =>
 350:       askUserImpl(tool, input, riskHint),
 351:     );
 352:     permissionPromptChain = run.catch(() => {});
 353:     return run;
 354:   };
 355: 
 356:   if (isInteractive && !quiet) {
 357:     renderWelcome({
 358:       version: "1.0.0",
 359:       model: modelConfig.model,
 360:       provider: modelConfig.provider,
 361:       workspaceRoot,
 362:     });
 363:   } else if (quiet) {
 364:     console.log(`Claude Code Replica (${modelConfig.provider}/${modelConfig.model}) — /help for commands, exit to quit`);
 365:   } else {
 366:     console.log('Type your request, /help for commands (or "exit" to quit):\n');
 367:   }
 368: 
 369:   // eslint-disable-next-line no-constant-condition
 370:   while (true) {
 371:     const userInput = await readInput();
 372: 
 373:     // null = stdin closed (EOF / Ctrl+D). Exit the REPL cleanly.
 374:     if (userInput === null) break;
 375:     if (!userInput.trim()) continue;
 376:     if (userInput.toLowerCase() === "exit") break;
 377: 
 378:     // Local slash commands run before anything is sent to the model.
 379:     if (userInput.startsWith("/")) {
 380:       const result = await handleSlashCommand(userInput, makeCommandContext());
 381:       if (result.exit) break;
 382:       if (result.handled) continue;
 383:     }
 384: 
 385:     // Expand @file references into context attachments.
 386:     const { attachments, notes } = expandFileRefs(userInput, workspaceRoot);
 387:     for (const note of notes) console.log(chalk.gray(note));
 388: 
 389:     const contentText =
 390:       attachments.length > 0
 391:         ? `${userInput}\n\n${attachments.join("\n\n")}`
 392:         : userInput;
 393: 
 394:     // Add user message
 395:     messages.push({
 396:       role: "user",
 397:       content: [{ type: "text", text: contentText }],
 398:     });
 399: 
 400:     // Per-turn abort handling: first Ctrl+C aborts the current turn and
 401:     // returns to the prompt; a second (at the idle prompt) exits.
 402:     const controller = new AbortController();
 403:     const onSigint = () => {
 404:       controller.abort("用户中断");
 405:     };
 406:     process.on("SIGINT", onSigint);
 407: 
 408:     const renderer = new StreamingRenderer();
 409:     const spinner = new Spinner();
 410: 
 411:     // The permission callback must pause the spinner while a menu is shown.
 412:     const askUserGuarded: AskUserFn = async (tool, input, riskHint) => {
 413:       const wasSpinning = spinner.isActive;
 414:       spinner.stop();
 415:       try {
 416:         return await askUser(tool, input, riskHint);
 417:       } finally {
 418:         if (wasSpinning) spinner.start();
 419:       }
 420:     };
 421: 
 422:     // Run agent loop
 423:     const loop = agentLoop(
 424:       messages,
 425:       tools,
 426:       callModel,
 427:       modelConfig,
 428:       {
 429:         systemPrompt,
 430:         maxTurns: 50,
 431:         toolContext: {
 432:           workspaceRoot,
 433:           sessionId: sessionId!,
 434:           permissionMode,
 435:           modelConfig,
 436:           onSubAgentProgress: (event) => {
 437:             spinner.stop();
 438:             renderer.flush();
 439:             renderSubAgentActivity(event);
 440:           },
 441:         },
 442:         askUser: askUserGuarded,
 443:         abortSignal: controller.signal,
 444:         hooks,
 445:       },
 446:     );
 447: 
 448:     let lastText = "";
 449:     let turnInputTokens = 0;
 450:     let turnOutputTokens = 0;
 451:     let streamedChars = 0;
 452:     let thinkingStart = 0;
 453:     let thoughtReported = false;
 454: 
 455:     for await (const event of loop) {
 456:       switch (event.type) {
 457:         case "thinking":
 458:           thinkingStart = Date.now();
 459:           thoughtReported = false;
 460:           spinner.setMode("thinking");
 461:           spinner.start();
 462:           break;
 463: 
 464:         case "text_delta":
 465:           // First visible text ends the "thinking" phase: print the
 466:           // "Thought for Ns" line, then switch the spinner to responding.
 467:           if (!thoughtReported && thinkingStart > 0) {
 468:             const secs = Math.max(1, Math.round((Date.now() - thinkingStart) / 1000));
 469:             spinner.stop();
 470:             console.log(chalk.dim(`  Thought for ${secs}s (ctrl+o to expand)`));
 471:             thoughtReported = true;
 472:           }
 473:           spinner.stop();
 474:           renderer.write(event.delta);
 475:           streamedChars += event.delta.length;
 476:           spinner.update({ tokens: Math.round(streamedChars / 4) });
 477:           lastText += event.delta;
 478:           break;
 479: 
 480:         case "tool_use":
 481:           spinner.stop();
 482:           renderer.flush();
 483:           renderToolStart(event.name, event.input);
 484:           spinner.setMode("tool");
 485:           spinner.start();
 486:           break;
 487: 
 488:         case "tool_results":
 489:           spinner.stop();
 490:           renderer.flush();
 491:           for (const result of event.results) {
 492:             renderToolResult(result);
 493:           }
 494:           // Auto-save after tool execution
 495:           persistence.save(sessionId!, messages).catch(() => {});
 496:           spinner.start();
 497:           break;
 498: 
 499:         case "compacting":
 500:           spinner.stop();
 501:           renderer.flush();
 502:           console.log("\n  Compacting context…");
 503:           break;
 504: 
 505:         case "usage":
 506:           turnInputTokens += event.usage.input_tokens;
 507:           turnOutputTokens += event.usage.output_tokens;
 508:           spinner.update({ tokens: turnOutputTokens || Math.round(streamedChars / 4) });
 509:           break;
 510: 
 511:         case "error":
 512:           spinner.stop();
 513:           renderer.flush();
 514:           console.error(`\n  ${chalk.red("⎿")} ${formatCliError(event.error)}`);
 515:           break;
 516: 
 517:         case "done":
 518:           spinner.stop();
 519:           renderer.flush();
 520:           if (uiState.showTokens && (turnInputTokens || turnOutputTokens)) {
 521:             console.log(
 522:               chalk.gray(
 523:                 `\n  [tokens: ${turnInputTokens} in / ${turnOutputTokens} out]`,
 524:               ),
 525:             );
 526:           }
 527:           // Final assistant text was added to messages in the loop
 528:           persistence.save(sessionId!, messages).catch(() => {});
 529:           break;
 530: 
 531:         case "aborted":
 532:           spinner.stop();
 533:           renderer.flush();
 534:           console.log(`\n  ${chalk.dim("⎿")} Aborted: ${event.reason}`);
 535:           break;
 536:       }
 537:     }
 538: 
 539:     spinner.stop();
 540: 
 541:     // Detach this turn's SIGINT handler so handlers don't stack up.
 542:     process.removeListener("SIGINT", onSigint);
 543: 
 544:     console.log(""); // New line after response
 545:     // Ensure Windows terminals paint the final buffered line before readline
 546:     // waits for the next prompt; otherwise the user may need to press Enter.
 547:     await new Promise<void>((resolve) => process.stdout.write("", () => resolve()));
 548:   }
 549: 
 550:   // Cleanup
 551:   closeInput();
 552:   await persistence.save(sessionId!, messages, { completed: true });
 553:   await mcpManager.disconnectAll();
 554:   console.log("\nGoodbye!");
 555: }
 556: 
 557: main().catch((error) => {
 558:   console.error("Fatal error:", formatCliError(error));
 559:   process.exit(1);
 560: });
